type Money struct{ Cents int64 }

func (m Money) Equal(o Money) bool { return m.Cents == o.Cents }
func (m Money) Compare(o Money) int { return cmp.Compare(m.Cents, o.Cents) }

// ordered type parameters, including named numeric/string types; structs cannot satisfy cmp.Ordered
func Max[T cmp.Ordered](a, b T) T { if a > b { return a }; return b }

// family-wide ordering for user types: a self-referential constraint
type Comparer[T any] interface{ Compare(T) int }
func Largest[E Comparer[E]](xs []E) E {
    if len(xs) == 0 { panic("empty slice") }
    best := xs[0]
    for _, x := range xs[1:] { if x.Compare(best) > 0 { best = x } }
    return best
}
